\section{From the notes

blocks.t:
\boxed{
\begin{aligned}
\min_{w,b,\xi}\quad & \tfrac12\|w\|^2 + C\sum_{i=1}^{n}\xi_i

\text{s.t.}\quad & y_i(w^Tx_i+b) \ge 1-\xi_i,\qquad \xi_i \ge 0 .
\end{aligned}}

\begin{array}{lll}
\alpha_i = 0 & \Rightarrow y_i f(x_i) \ge 1, \xi_i=0
 & \text{non-SV, outside the margin}
[2pt]
0 < \alpha_i < C & \Rightarrow y_i f(x_i) = 1, \xi_i=0
 & free / margin SV — exactly on the line
[2pt]
\alpha_i = C & \Rightarrow y_i f(x_i) \le 1, \xi_i>0
 & bounded SV — a violator
\end{array}
